from html.parser import HTMLParser
s=json.load(open('source.json'));a=json.load(open('answer.json'));r=json.load(open('reference-targets.json'))
allowed=set('p br table thead tbody tfoot tr th td b strong i em u sup sub ul ol li div span blockquote'.split())
class Check(HTMLParser):
 def handle_starttag(self,t,attrs):
  assert t in allowed,t
  for k,v in attrs: assert k in {'rowspan','colspan'} and v.isdigit(),(k,v)
def text(x):return html.unescape(re.sub('<["'^>]+>'"','',x or ''))
assert len(a)==len(s)==24
for i,(src,out) in enumerate(zip(s,a)):
 for k in ['code_id','source_id','source_sha256','number']: assert out[k]==src[k],(i,k)
 assert out['status'] in ['retained_unchanged','rewrite_draft']
 si=out['substantive_impact'];assert si['version']==1
 for k in ['assessment','scope_limitations','new_burdens_review']:assert len(si[k])>=40,(i,k)
 p=out['proposed_xml']
 if p is None: assert out['status']=='retained_unchanged' and out['classification']=='retained_necessary' and si['classification']=='retained_necessary' and not si['effects']
 else:
  Check().feed(p)
  if out.get('change_type')=='full_repeal':assert text(p).startswith(('Le présent article est abrogé','Abrogé')) and len(out['repeal_scope'])>=30 and out['repeal_policy_id']=='editorial_direction_2026_10_19'
  if out.get('change_type')=='normative_reduction':assert all(len(x)>=30 for x in out['removed_provisions']) and out['reform_policy_id']=='editorial_direction_2026_10_19'
 if src.get('benefit_check_required'):assert len(out.get('benefit_review',''))>=100
 req=r['requirements'][src['code_id']+'|'+src['source_id']];checks=out['reference_checks'];assert [c['target_key'] for c in checks]==req,(i,'target list')
 for c in checks:assert c['view_sha256']==r['targets'][c['target_key']]['view_sha256'] and len(c['assessment'])>=80
 for e in si['effects']:
  assert re.fullmatch('[a-z0-9]+(?:-[a-z0-9]+)*',e['measure_id']) and 6<=len(e['measure_id'])<=96
  for field,body in [('source_quote',src['source_xml']),('proposed_quote',p)]:
   assert len(e[field])>=12 and e[field] in text(body),(i,field,e[field])
 print(i,out['number'],out['status'],out.get('change_type','-'),si['classification'],len(p or ''),'refs',len(checks),'effects',len(si['effects']))
print('VALIDATION OK',collections.Counter(x['substantive_impact']['classification'] for x in a))
